"""Render an offline, aggregate-only interactive research evidence viewer."""
from __future__ import annotations
import hashlib
import json
from pathlib import Path
import pandas as pd

ROOT = Path(__file__).resolve().parent


def main():
    out = ROOT / "outputs/oversight"
    read = lambda name: json.loads((out / name).read_text(encoding="utf-8"))
    baseline, incidents, receipt = map(read, ["validation_summary.json", "incident_summary.json", "run_receipt.json"])
    if receipt["status"] != "PASS": raise RuntimeError("Release evidence is not passing.")
    data = {"baseline": baseline, "incidents": incidents, "receipt": receipt,
            "scenarios": pd.read_csv(ROOT / "outputs/wrds/scenario_summary.csv").to_dict("records"),
            "stress": read("historical_stress.json")}
    encoded = json.dumps(data, allow_nan=False).replace("<", "\\u003c")
    template = r'''<!doctype html>
<html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<meta name="description" content="Independent portfolio validation, controlled failure investigations and investment implementation economics.">
<title>Portfolio Oversight | Josh Gutierrez</title>
<style>
:root{--ink:#142d42;--muted:#4a6072;--line:#cbd6df;--paper:#fff;--bg:#f1f5f7;--teal:#00645e;--red:#9a292e;--soft:#e7f3ef;--focus:#145dd1;--space:24px}
*{box-sizing:border-box}body{margin:0;background:var(--bg);color:var(--ink);font:16px/1.55 system-ui,-apple-system,"Segoe UI",sans-serif}a{color:#064c91}a:hover{text-decoration-thickness:2px}button,select{font:inherit;min-height:44px;border:1px solid var(--line);background:white;color:var(--ink);padding:8px 12px;border-radius:3px}button{cursor:pointer}button:hover{background:#e6eef3}:focus-visible{outline:3px solid var(--focus);outline-offset:3px}.skip{position:absolute;left:12px;top:-80px;padding:12px;background:white;z-index:4}.skip:focus{top:10px}
header{background:var(--ink);color:white;padding:26px max(24px,calc((100vw - 1180px)/2)) 30px}header a{color:#c5e8ff}.brand{font-size:13px;text-transform:uppercase;letter-spacing:.14em;color:#c7d9e7}h1{font-size:clamp(29px,4vw,43px);line-height:1.15;letter-spacing:-.035em;margin:12px 0}header p{max-width:800px;margin:12px 0 0;color:#dfebf4}main{max-width:1228px;margin:auto;padding:24px}.metric-row{display:grid;grid-template-columns:repeat(4,1fr);gap:14px}.metric{background:white;border:1px solid var(--line);padding:16px 18px}.metric b{font-size:29px;display:block;line-height:1.25;color:var(--teal)}.metric span{font-size:13px;color:var(--muted)}.panel{margin:22px 0;background:white;border:1px solid var(--line);padding:24px}h2{margin:0 0 12px;font-size:23px;letter-spacing:-.02em}h3{font-size:17px;margin:14px 0 8px}p{margin:8px 0 14px}.note{font-size:13px;color:var(--muted)}.decision{border-left:5px solid var(--teal)}.controls{display:flex;flex-wrap:wrap;gap:10px;align-items:center;margin:12px 0 18px}.table-wrap{overflow:auto;max-width:100%;border:1px solid var(--line)}table{border-collapse:collapse;width:100%;font-size:14px}th,td{padding:11px 13px;text-align:left;border-bottom:1px solid #e3e9ee;vertical-align:top}th{background:#edf2f5;white-space:nowrap}td.num,th.num{text-align:right;font-variant-numeric:tabular-nums;white-space:nowrap}tbody tr:last-child td{border-bottom:0}.badge{display:inline-block;font-size:12px;font-weight:700;padding:3px 7px;border:1px solid #9db7b0;color:var(--teal);background:var(--soft)}.block{color:var(--red);background:#fff2f1;border-color:#d9aaaa}.split{display:grid;grid-template-columns:1.1fr 1fr;gap:24px}.case-nav{display:flex;gap:7px;flex-wrap:wrap}.case-nav button[aria-pressed=true]{background:var(--ink);color:white;border-color:var(--ink)}.mono{font-family:ui-monospace,Consolas,monospace;font-size:12px;overflow-wrap:anywhere}.downloads{display:flex;gap:14px;flex-wrap:wrap}.downloads a{display:inline-block;padding:10px 13px;border:1px solid var(--line);text-decoration:none;font-weight:600}.downloads a:hover{background:#edf3f7}.barline{display:grid;grid-template-columns:130px 1fr 82px;gap:10px;align-items:center;margin:12px 0;font-size:14px}.track{background:#e5ecef;height:15px}.bar{background:var(--teal);height:100%;min-width:1px}.barline b{text-align:right;font-variant-numeric:tabular-nums}details summary{cursor:pointer;padding:8px 0;min-height:44px}footer{padding:0 24px 28px;max-width:1228px;margin:auto;color:var(--muted);font-size:13px}code{font-family:ui-monospace,Consolas,monospace;font-size:.9em}ul{padding-left:22px}li{margin:6px 0}#status{min-height:20px}
#control-table{max-height:500px}#control-table thead{position:sticky;top:0;z-index:1}
@media(max-width:800px){.metric-row{grid-template-columns:repeat(2,1fr)}.split{grid-template-columns:1fr}.panel{padding:17px}main{padding:16px}header{padding:24px 18px}.barline{grid-template-columns:110px 1fr 65px;font-size:12px}.downloads{gap:8px}.controls select{width:100%}}@media(prefers-reduced-motion:reduce){*{scroll-behavior:auto!important}}
</style></head><body><a class="skip" href="#main">Skip to research evidence</a>
<header><div class="brand">Josh Gutierrez · Investment research</div><h1>Portfolio Validation &amp;<br>Investment Oversight</h1><p>Would I approve this rebalance—and can I independently explain its risks, costs and performance?</p><p class="note" style="color:#d5e3ed">Actual WRDS/CRSP historical research · Hypothetical accounts · Deliberately injected failure cases</p></header>
<main id="main"><div class="metric-row" aria-label="Verified run results"><div class="metric"><b id="baseline"></b><span>Baseline technical validation</span></div><div class="metric"><b id="cases"></b><span>Injected faults correctly blocked</span></div><div class="metric"><b id="paths"></b><span>Portfolio paths reconstructed</span></div><div class="metric"><b id="retest"></b><span>Corrected-input retest</span></div></div>
<section class="panel decision"><h2>The investment decision</h2><p>For the <strong>No gold</strong> account, avoiding trades saved only about <strong>$110 annually per constant $1m</strong> at the assumed cost rate, while accepting about <strong>27bp more realized tracking risk</strong>.</p><p>Prefer tighter tracking when mandate fidelity is the priority. Choose lower turnover only when the client's objective justifies the additional risk. A technical PASS is not an investment approval.</p><div class="downloads"><a href="../outputs/oversight/Portfolio_Oversight_Memo.pdf">Decision memo · PDF</a><a href="../outputs/oversight/Portfolio_Oversight.xlsx">Control workbook · Excel</a><a href="../outputs/oversight/Interview_Guide.pdf">Detailed interview guide · PDF</a><a href="https://github.com/JoshGutierrez56/personalized-model-portfolios">Source &amp; reproducibility</a></div></section>
<section class="panel"><h2>Challenge a result</h2><p>Each case modifies an in-memory copy. Detection requires the relevant economic or structural check to fail—not merely a changed file hash. Restoring the unchanged original inputs must pass.</p><div id="case-nav" class="case-nav" aria-label="Select an injected test case"></div><div id="case-body" aria-live="polite"></div></section>
<section class="panel"><h2>Inspect the implementation trade-off</h2><div class="controls"><label for="scenario">Hypothetical account</label><select id="scenario"></select></div><div class="split"><div><h3>Realized gross tracking error</h3><div id="riskbars"></div><p class="note">Annualized standard deviation of daily active returns, in %. Lower tracking error is not higher expected return.</p></div><div><h3>Annualized modeled costs</h3><div id="costbars"></div><p class="note">Basis points of portfolio NAV per year; 5bp per dollar bought or sold. Costs funded from the account.</p></div></div><div id="scenario-table" class="table-wrap" tabindex="0" aria-label="Scenario result table; scroll horizontally on small screens"></div><p id="status" class="note" aria-live="polite"></p></section>
<section class="panel"><h2>Independent control evidence</h2><p>Separate contract, arithmetic and versioned SQL. No production optimizer or validation functions are imported. Inputs and the Ledoit–Wolf numerical dependency are shared; independent code is not independent market data.</p><div class="controls"><label for="control-filter">Show controls</label><select id="control-filter"><option value="all">All controls</option><option value="reconciliation">Reconciliation and accounting</option><option value="risk">Risk and constraints</option><option value="data">Data and chronology</option></select></div><p id="control-count" class="note" aria-live="polite"></p><div id="control-table" class="table-wrap" tabindex="0" aria-label="Control results table"></div></section>
<section class="panel"><h2>What these results do—and do not—establish</h2><div class="split"><div><h3>Evidence</h3><ul><li>Eight ETFs; 32,192 CRSP observations, 2010–2025 source history.</li><li>2014–2025 evaluation, 30 account/method paths and 4,320 decisions.</li><li>Self-financing trades, prior-close decisions, drifting holdings and independently linked return contributions.</li><li>Traceable block → diagnosis → correction → retest workflow.</li></ul></div><div><h3>Boundaries</h3><ul><li>Current-vintage, retrospectively selected universe; already-exposed historical sample.</li><li>No live orders, actual clients, tax-lot engine, stock-level factor model or alpha claim.</li><li>Injected failures are tests, not real production incidents.</li><li>Licensed source rows and detailed security-day ledgers remain private.</li></ul></div></div><details><summary>Run provenance and tolerances</summary><p id="run-id" class="mono"></p><p class="note">Tolerance definitions are in oversight_contract.json. Dollar/return/weight units differ; count controls report zero permitted failures. “Max error” for boolean controls is 0 or 1, not a financial amount.</p><p><a href="../outputs/oversight/run_receipt.json">Run receipt</a> · <a href="../outputs/oversight/validation_summary.json">Full validation summary</a> · <a href="../outputs/oversight/incident_summary.json">Incident evidence</a> · <a href="OVERSIGHT_METHODOLOGY.md">Methodology</a></p></details></section></main>
<footer>Built with AI coding and drafting assistance. A research demonstration, not a production investment platform. The presenter should be able to explain and defend the calculations and decisions.</footer>
<script type="application/json" id="evidence">__DATA__</script><script>
'use strict';const D=JSON.parse(document.getElementById('evidence').textContent);const $=id=>document.getElementById(id);const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));const num=(x,n=2)=>Number(x).toLocaleString('en-US',{minimumFractionDigits:n,maximumFractionDigits:n});const tiny=x=>x===null?'Unavailable':Number(x)===0?'0':Number(x).toExponential(2);
$('baseline').textContent=D.baseline.status;$('cases').textContent=`${D.receipt.detected_cases}/${D.receipt.injected_cases}`;$('paths').textContent=D.baseline.aggregate.paths;$('retest').textContent=D.receipt.corrected_retest_status;$('run-id').textContent=`${D.receipt.run_id} | ${D.receipt.completed_utc} | Original inputs unchanged: ${D.receipt.original_inputs_unchanged}`;
function table(headers,rows){return '<table><thead><tr>'+headers.map(h=>'<th>'+esc(h)+'</th>').join('')+'</tr></thead><tbody>'+rows.map(r=>'<tr>'+r.map(v=>'<td>'+esc(v)+'</td>').join('')+'</tr>').join('')+'</tbody></table>'}
function showCase(index){const c=D.incidents.cases[index];document.querySelectorAll('#case-nav button').forEach((b,i)=>b.setAttribute('aria-pressed',String(i===index)));$('case-body').innerHTML='<h3>'+esc(c.title)+' <span class="badge block">'+esc(c.observed_status)+'</span></h3><p class="note">'+esc(c.classification)+'</p><div class="split"><div><p><strong>Injected change:</strong> '+esc(c.injection)+'</p><p><strong>Root cause:</strong> '+esc(c.root_cause)+'</p><p><strong>Correction:</strong> '+esc(c.corrective_action)+'</p></div><div><p><strong>Acceptance:</strong> '+esc(c.acceptance_criterion)+'</p><p><strong>Domain-specific detection:</strong> '+esc(c.expected_domain_failure_observed)+'</p><p><strong>Corrected retest:</strong> <span class="badge">'+esc(c.corrected_retest)+'</span> · '+esc(c.closure)+'</p><p class="note">Full corrupted-input replay is a diagnostic disagreement, not an investable alternative strategy.</p></div></div><details><summary>Failed controls ('+c.failed_checks.length+')</summary><div class="table-wrap">'+table(['Control','Max error','Tolerance'],c.failed_checks.map(v=>[v.id,tiny(v.max_abs_error),tiny(v.tolerance)]))+'</div></details>'}
D.incidents.cases.forEach((c,i)=>{let b=document.createElement('button');b.type='button';b.textContent=c.id;b.setAttribute('aria-pressed','false');b.addEventListener('click',()=>showCase(i));$('case-nav').append(b)});showCase(0);
const scenarios=[...new Set(D.scenarios.map(r=>r.client))];scenarios.forEach(s=>{let o=document.createElement('option');o.value=s;o.textContent=s;$('scenario').append(o)});$('scenario').value='No gold';
function bars(rows,key,digits,suffix){let max=Math.max(...rows.map(r=>r[key]),1e-9);return rows.map(r=>'<div class="barline"><span>'+esc(r.method)+'</span><div class="track" aria-hidden="true"><div class="bar" style="width:'+Math.max(0,r[key]/max*100)+'%"></div></div><b>'+num(r[key],digits)+suffix+'</b></div>').join('')}
function scenario(){let rows=D.scenarios.filter(r=>r.client===$('scenario').value);$('riskbars').innerHTML=bars(rows,'gross_te_pct',2,'%');$('costbars').innerHTML=bars(rows,'annual_incurred_cost_bps',2,'bp');$('scenario-table').innerHTML=table(['Method','Gross TE (%)','One-way turnover (%/yr)','Cost (bp NAV/yr)','Terminal NAV ($)'],rows.map(r=>[r.method,num(r.gross_te_pct),num(r.annual_one_way_turnover_pct),num(r.annual_incurred_cost_bps),num(r.terminal_nav,0)]));$('status').textContent=`${rows.length} methods shown for ${$('scenario').value}. Same restrictions, source history and cost assumption; different optimization objectives.`}scenario();$('scenario').addEventListener('change',scenario);
function controls(){let mode=$('control-filter').value,rows=D.baseline.checks.filter(c=>mode==='all'||(mode==='reconciliation'?/recon|sql_|link|funding|contribution|formula/.test(c.id):mode==='risk'?/risk|constraint|weight|investment/.test(c.id):/schema|keys|calendar|roster|source|date|chronology|window|drift/.test(c.id)));$('control-count').textContent=`${rows.length} of ${D.baseline.checks.length} controls shown`;$('control-table').innerHTML=table(['Control','Status','Comparisons','Max error','Tolerance'],rows.map(c=>[c.id,c.status,num(c.count,0),tiny(c.max_abs_error),tiny(c.tolerance)]))}controls();$('control-filter').addEventListener('change',controls);
</script></body></html>'''
    target = ROOT / "docs/index.html"
    target.write_text(template.replace("__DATA__", encoded), encoding="utf-8")
    # Static site links need repository-hosted raw downloads, not absent Pages output paths.
    html = target.read_text(encoding="utf-8")
    html = html.replace('href="../outputs/', 'href="https://raw.githubusercontent.com/JoshGutierrez56/personalized-model-portfolios/main/outputs/')
    html = html.replace('href="OVERSIGHT_METHODOLOGY.md"', 'href="https://github.com/JoshGutierrez56/personalized-model-portfolios/blob/main/docs/OVERSIGHT_METHODOLOGY.md"')
    target.write_text(html, encoding="utf-8")
    print(json.dumps({"path":"docs/index.html","bytes":target.stat().st_size,"sha256":hashlib.sha256(target.read_bytes()).hexdigest()}))


if __name__ == '__main__': main()
